import heapq

def match(orders):
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> [side, price, qty, seq]
    trades = []
    seq_counter = 0

    def add_order(side, id, price, qty, seq):
        book[id] = [side, price, qty, seq]
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, id))
        else:
            heapq.heappush(sell_heap, (price, seq, id))

    def pop_valid_top(heap, side):
        while heap:
            item = heap[0]
            oid = item[2]
            if oid in book and book[oid][2] > 0 and book[oid][0] == side:
                return item
            heapq.heappop(heap)
        return None

    for order in orders:
        seq_counter += 1
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
            opp_side = 'sell'
        else:
            opp_heap = buy_heap
            opp_side = 'buy'

        while remaining > 0:
            top = pop_valid_top(opp_heap, opp_side)
            if top is None:
                break
            top_id = top[2]
            top_price = book[top_id][1]

            if typ != 'market':
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            resting = book[top_id]
            trade_qty = min(remaining, resting[2])

            if side == 'buy':
                trades.append([oid, top_id, top_price, trade_qty])
            else:
                trades.append([top_id, oid, top_price, trade_qty])

            remaining -= trade_qty
            resting[2] -= trade_qty

            if resting[2] == 0:
                del book[top_id]
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            add_order(side, oid, price, remaining, seq_counter)

    return trades

